//! End-to-end tests for the deg-nexustk evidence kinds, driving the same
//! parse → index → artifacts → check path as `deg-nexustk check`.
//!
//! Positive tests replay the committed synthetic fixtures (generated by
//! `tools/gen_fixtures.py`); negative tests tamper copies of them and
//! assert the documented failure messages.

use deg::artifact::ArtifactSet;
use deg::json::Json;
use deg::kernel::{self, CheckReport};
use deg::parser::parse_model;
use deg::semantic::ModelIndex;
use deg::sha256::sha256_hex;
use deg::strength::Strength;
use deg::value::Value;
use std::collections::BTreeMap;
use std::fs;
use std::path::{Path, PathBuf};

/// Recompute a manifest's seal digest in place after a test tampered a
/// non-seal field, so the digest check passes and the test targets the check
/// under review (blob/file existence and hashes). Returns the new digest.
fn reseal_manifest(obj: &mut BTreeMap<String, Json>) -> String {
    let mut payload = obj.clone();
    payload.remove("seal");
    payload.remove("verify");
    let digest = sha256_hex(deg_nexustk::bundle::canonical_json(&Json::Obj(payload)).as_bytes());
    let seal = obj.get_mut("seal").expect("manifest has a seal object");
    let Json::Obj(sig) = seal else {
        panic!("seal is an object");
    };
    sig.insert("sha256".to_string(), Json::Str(digest.clone()));
    digest
}

fn synth_dir() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("examples/synthetic")
}

fn tmp_dir(name: &str) -> PathBuf {
    // CARGO_TARGET_TMPDIR lives under the workspace target directory, which
    // is gitignored.
    let dir = Path::new(env!("CARGO_TARGET_TMPDIR"))
        .join("adapters")
        .join(name);
    fs::create_dir_all(&dir).unwrap();
    dir
}

/// Copy a file and return its path.
fn copy_file(src: &Path, dst_dir: &Path, name: &str) -> PathBuf {
    let dst = dst_dir.join(name);
    fs::copy(src, &dst).unwrap();
    dst
}

fn copy_dir(src: &Path, dst: &Path) {
    fs::create_dir_all(dst).unwrap();
    for entry in fs::read_dir(src).unwrap() {
        let entry = entry.unwrap();
        let from = entry.path();
        let to = dst.join(entry.file_name());
        if from.is_dir() {
            copy_dir(&from, &to);
        } else {
            fs::copy(&from, &to).unwrap();
        }
    }
}

fn dataset_decl(name: &str, path: &Path) -> String {
    let bytes = fs::read(path).unwrap();
    format!(
        "dataset {name} = dataset({:?}, sha256: {:?});\n",
        path.display().to_string(),
        sha256_hex(&bytes)
    )
}

fn run_evidence(model_src: &str, evidence_name: &str) -> (ModelIndex, ArtifactSet, CheckReport) {
    // Extension registration is global and once-only per process.
    static REGISTER: std::sync::Once = std::sync::Once::new();
    REGISTER.call_once(deg_nexustk::register);

    let model = parse_model("adapters.dg", model_src).expect("model parses");
    let index = ModelIndex::new(&model).expect("model indexes");
    let artifacts = ArtifactSet::load(&model, None);
    assert!(
        artifacts.errors.is_empty(),
        "artifact errors: {:?}",
        artifacts.errors
    );
    let report = kernel::check(&index, &artifacts);
    let outcome = report
        .evidence
        .get(evidence_name)
        .unwrap_or_else(|| panic!("evidence {evidence_name} was evaluated"));
    assert_eq!(outcome.ok, report.ok, "outcome and report disagree");
    (index, artifacts, report)
}

fn has_fact(outcome: &deg::evidence::EvidenceOutcome, rel: &str, args: &[Value]) -> bool {
    outcome.facts.iter().any(|(r, a)| r == rel && a == args)
}

fn evidence_of<'a>(report: &'a CheckReport, name: &str) -> &'a deg::evidence::EvidenceOutcome {
    report.evidence.get(name).unwrap()
}

// --------------------------------------------------------------------- vector

#[test]
fn synthetic_vectors_replay_as_deterministic_evidence() {
    let ds_path = synth_dir().join("vectors-synthetic.json");
    let mut src = dataset_decl("ds_vec", &ds_path);
    src.push_str("ev e := ntk_vector(ds_vec, suite: \"all\");\n");
    let (_index, _artifacts, report) = run_evidence(&src, "e");

    let outcome = evidence_of(&report, "e");
    assert!(outcome.ok, "error: {:?}", outcome.error);
    assert_eq!(outcome.strength, Strength::Deterministic);
    assert!(has_fact(
        outcome,
        "vector_suite_ok",
        &[Value::sym("e"), Value::sym("all")]
    ));
    assert!(has_fact(
        outcome,
        "vector_count",
        &[Value::sym("e"), Value::sym("all"), Value::Int(14)]
    ));
    assert!(has_fact(
        outcome,
        "cipher_vector_ok",
        &[
            Value::sym("e"),
            Value::sym("deg-cipher-table"),
            Value::sym("s2c"),
            Value::Int(0x0C)
        ]
    ));
    assert!(has_fact(
        outcome,
        "frame_vector_ok",
        &[
            Value::sym("e"),
            Value::sym("deg-frame-arrival"),
            Value::sym("c2s"),
            Value::Int(0x10)
        ]
    ));
    assert!(has_fact(
        outcome,
        "stream_vector_ok",
        &[
            Value::sym("e"),
            Value::sym("deg-stream-login-mixed"),
            Value::sym("s2c")
        ]
    ));
    assert!(has_fact(
        outcome,
        "keytable_ok",
        &[Value::sym("e"), Value::sym("deg-keytable-a")]
    ));
    // Per-suite counts appear as details.
    assert!(outcome
        .details
        .iter()
        .any(|(k, v)| k == "ciphers" && v == "4"));
    assert!(outcome
        .details
        .iter()
        .any(|(k, v)| k == "frames" && v == "4"));
}

#[test]
fn unknown_vector_suite_fails_loudly() {
    let ds_path = synth_dir().join("vectors-synthetic.json");
    let mut src = dataset_decl("ds_vec", &ds_path);
    src.push_str("ev e := ntk_vector(ds_vec, suite: \"nope\");\n");
    let (_index, _artifacts, report) = run_evidence(&src, "e");
    let outcome = evidence_of(&report, "e");
    assert!(!outcome.ok);
    let error = outcome.error.as_deref().unwrap_or("");
    assert!(error.contains("unknown vector suite"), "{error}");
}

// --------------------------------------------------------------------- frames

#[test]
fn synthetic_frames_emit_only_structural_facts() {
    let ds_path = synth_dir().join("frames-synthetic.jsonl");
    let mut src = dataset_decl("ds_frames", &ds_path);
    src.push_str("ev e := ntk_frames(ds_frames);\n");
    let (_index, _artifacts, report) = run_evidence(&src, "e");

    let outcome = evidence_of(&report, "e");
    assert!(outcome.ok, "error: {:?}", outcome.error);
    assert_eq!(outcome.strength, Strength::Observational);
    assert!(has_fact(
        outcome,
        "frame_count",
        &[Value::sym("e"), Value::Int(29)]
    ));
    // Frame facts exist for both directions.
    let frames = outcome
        .facts
        .iter()
        .filter(|(rel, _)| rel == "frame")
        .collect::<Vec<_>>();
    assert_eq!(frames.len(), 29);
    assert!(frames
        .iter()
        .any(|(_, a)| a.get(1) == Some(&Value::sym("in"))));
    assert!(frames
        .iter()
        .any(|(_, a)| a.get(1) == Some(&Value::sym("out"))));
    // The truncated-body row reports the declared captured length, not the
    // hex-char count of the `…<8>`-suffixed bodyHex.
    assert!(frames.iter().any(|(_, a)| a.get(4) == Some(&Value::Int(8))));
    // Redaction: no fact argument is a byte blob.
    for (_, args) in &outcome.facts {
        assert!(
            !args.iter().any(|a| matches!(a, Value::Bytes(_))),
            "a fact carries body bytes"
        );
    }
    // Two deliberately malformed lines plus the non-frame `connect` event
    // line were skipped with a note.
    assert!(outcome
        .details
        .iter()
        .any(|(k, v)| k == "skipped_lines" && v == "3"));
    assert!(outcome
        .details
        .iter()
        .any(|(k, v)| k == "redaction" && v.contains("never emitted")));
}

#[test]
fn frames_use_declared_lengths_and_skip_non_frame_events() {
    let tmp = tmp_dir("frames-declared");
    let jsonl = tmp.join("frames.jsonl");
    fs::write(
        &jsonl,
        concat!(
            "{\"dir\":\"in\",\"stage\":\"wire.recv\",\"channel\":\"game\",\"op\":12,",
            "\"event\":\"frame\",\"bodyHex\":\"aabbccddeeff00112233…<8>\",",
            "\"bodyHexTruncated\":true,\"bodyHexCaptured\":8,\"bodyDeclaredLen\":8}\n",
            "{\"dir\":\"event\",\"stage\":\"connect\",\"channel\":\"unknown\",",
            "\"op\":null,\"event\":\"connect\"}\n",
            "{\"dir\":\"out\",\"stage\":\"wire.send\",\"channel\":\"login\",\"op\":0,",
            "\"event\":\"frame\",\"bodyHex\":\"aabb\",\"ts\":1794422049000}\n",
        ),
    )
    .unwrap();
    let mut src = dataset_decl("ds_frames", &jsonl);
    src.push_str("ev e := ntk_frames(ds_frames);\n");
    let (_index, _artifacts, report) = run_evidence(&src, "e");
    let outcome = evidence_of(&report, "e");
    assert!(outcome.ok, "error: {:?}", outcome.error);
    assert!(has_fact(
        outcome,
        "frame_count",
        &[Value::sym("e"), Value::Int(2)]
    ));
    // The first frame's body length comes from bodyDeclaredLen (8), not the
    // hex-char count of the truncated bodyHex.
    assert!(outcome
        .facts
        .iter()
        .any(|(rel, a)| rel == "frame" && a.get(4) == Some(&Value::Int(8))));
    // The second frame counts hex chars (2 bytes).
    assert!(outcome
        .facts
        .iter()
        .any(|(rel, a)| rel == "frame" && a.get(4) == Some(&Value::Int(2))));
    // The connect event was skipped and counted.
    assert!(outcome
        .details
        .iter()
        .any(|(k, v)| k == "skipped_lines" && v == "1"));
}

#[test]
fn frames_over_max_frames_fails() {
    let ds_path = synth_dir().join("frames-synthetic.jsonl");
    let mut src = dataset_decl("ds_frames", &ds_path);
    src.push_str("ev e := ntk_frames(ds_frames, max_frames: 5);\n");
    let (_index, _artifacts, report) = run_evidence(&src, "e");
    let outcome = evidence_of(&report, "e");
    assert!(!outcome.ok);
    let error = outcome.error.as_deref().unwrap_or("");
    assert!(error.contains("frame count exceeds max_frames"), "{error}");
}

// --------------------------------------------------------------------- bundle

fn bundle_model(tmp: &Path) -> String {
    let mut src = dataset_decl("ds_manifest", &tmp.join("manifest.json"));
    src.push_str(&dataset_decl("ds_index", &tmp.join("index.json")));
    src.push_str(
        "ev e := ntk_bundle(ds_manifest, \"bnd_deg_synthetic_752\", index_ds: ds_index);\n",
    );
    src
}

fn bundle_copy(tmp: &Path) {
    let bundle = synth_dir().join("bundle");
    copy_file(&bundle.join("manifest.json"), tmp, "manifest.json");
    copy_file(&bundle.join("evidence.json"), tmp, "evidence.json");
    copy_file(&bundle.join("index.json"), tmp, "index.json");
    copy_dir(&bundle.join("blobs"), &tmp.join("blobs"));
}

#[test]
fn synthetic_bundle_verifies_as_deterministic_evidence() {
    let tmp = tmp_dir("bundle-ok");
    bundle_copy(&tmp);
    let src = bundle_model(&tmp);
    let (_index, _artifacts, report) = run_evidence(&src, "e");

    let outcome = evidence_of(&report, "e");
    assert!(outcome.ok, "error: {:?}", outcome.error);
    assert_eq!(outcome.strength, Strength::Deterministic);
    assert!(has_fact(
        outcome,
        "bundle_entries",
        &[Value::sym("e"), Value::Int(7)]
    ));
    assert!(has_fact(
        outcome,
        "bundle_blobs",
        &[Value::sym("e"), Value::Int(2)]
    ));
    assert!(has_fact(
        outcome,
        "bundle_evidence_ok",
        &[Value::sym("e"), Value::sym("evidence.json")]
    ));
    let blobs = outcome
        .facts
        .iter()
        .filter(|(rel, _)| rel == "blob_ok")
        .count();
    assert_eq!(blobs, 2);
    // The manifest sha256 in the fact matches the dataset's actual bytes.
    let manifest_sha = sha256_hex(&fs::read(tmp.join("manifest.json")).unwrap());
    assert!(has_fact(
        outcome,
        "bundle_verified",
        &[
            Value::sym("e"),
            Value::sym("bnd_deg_synthetic_752"),
            Value::sym(manifest_sha),
        ]
    ));
    assert!(outcome
        .details
        .iter()
        .any(|(k, v)| k == "index" && v.starts_with("pinned")));
}

#[test]
fn tampered_blob_fails_with_named_mismatch() {
    let tmp = tmp_dir("bundle-tampered-blob");
    bundle_copy(&tmp);
    // Flip one byte of the manifest's FIRST blob entry. The canonical blob
    // path is derived from that entry's declared sha256, so the evaluator
    // reports it as "blob 0" deterministically (a raw directory walk would
    // have arbitrary order).
    let manifest_path = tmp.join("manifest.json");
    let root = deg::json::parse(&fs::read_to_string(&manifest_path).unwrap()).unwrap();
    let blobs = root.get("blobs").unwrap().as_arr().unwrap();
    let first = blobs[0].as_obj().unwrap();
    let sha = first.get("sha256").unwrap().as_str().unwrap();
    let blob_path = tmp
        .join("blobs")
        .join("sha256")
        .join(&sha[0..2])
        .join(&sha[2..4])
        .join(sha);
    let mut bytes = fs::read(&blob_path).unwrap();
    bytes[0] ^= 0x01;
    fs::write(&blob_path, &bytes).unwrap();

    let src = bundle_model(&tmp);
    let (_index, _artifacts, report) = run_evidence(&src, "e");
    let outcome = evidence_of(&report, "e");
    assert!(!outcome.ok);
    let error = outcome.error.as_deref().unwrap_or("");
    assert!(error.contains("blob 0 hash mismatch"), "{error}");
}

#[test]
fn tampered_manifest_fails_verify_digest() {
    let tmp = tmp_dir("bundle-tampered-manifest");
    bundle_copy(&tmp);
    let manifest_path = tmp.join("manifest.json");
    let text = fs::read_to_string(&manifest_path).unwrap();
    let tampered = text.replace(
        "\"operator_alias\": \"deg-synthetic\"",
        "\"operator_alias\": \"deg-synthetic-x\"",
    );
    assert_ne!(tampered, text);
    fs::write(&manifest_path, tampered).unwrap();

    let src = bundle_model(&tmp);
    let (_index, _artifacts, report) = run_evidence(&src, "e");
    let outcome = evidence_of(&report, "e");
    assert!(!outcome.ok);
    let error = outcome.error.as_deref().unwrap_or("");
    assert!(error.contains("manifest verify digest mismatch"), "{error}");
}

#[test]
fn missing_index_leaves_the_hash_chain_unpinned() {
    let tmp = tmp_dir("bundle-no-index");
    bundle_copy(&tmp);
    let mut src = dataset_decl("ds_manifest", &tmp.join("manifest.json"));
    src.push_str("ev e := ntk_bundle(ds_manifest, \"bnd_deg_synthetic_752\");\n");
    let (_index, _artifacts, report) = run_evidence(&src, "e");
    let outcome = evidence_of(&report, "e");
    assert!(outcome.ok, "error: {:?}", outcome.error);
    assert!(outcome
        .details
        .iter()
        .any(|(k, v)| k == "index" && v.contains("hash chain not pinned")));
}

#[test]
fn tampered_blob_sha256_fails() {
    // Live-style blob entries declare `sha256` and no path; a tampered
    // declared digest derives a path whose file does not exist.
    let tmp = tmp_dir("bundle-tampered-blob-sha");
    bundle_copy(&tmp);
    let manifest_path = tmp.join("manifest.json");
    let mut root = deg::json::parse(&fs::read_to_string(&manifest_path).unwrap()).unwrap();
    let Json::Obj(obj) = &mut root else {
        panic!("manifest is an object");
    };
    let Json::Arr(blobs) = obj.get_mut("blobs").unwrap() else {
        panic!("blobs is an array");
    };
    let Json::Obj(first) = &mut blobs[0] else {
        panic!("blob entry is an object");
    };
    first.insert("sha256".to_string(), Json::Str("1".repeat(64)));
    reseal_manifest(obj);
    fs::write(&manifest_path, root.to_string()).unwrap();

    // Only the manifest dataset: the index pin is not under test here, and
    // the tampered manifest changes the seal digest it would pin.
    let mut src = dataset_decl("ds_manifest", &tmp.join("manifest.json"));
    src.push_str("ev e := ntk_bundle(ds_manifest, \"bnd_deg_synthetic_752\");\n");
    let (_index, _artifacts, report) = run_evidence(&src, "e");
    let outcome = evidence_of(&report, "e");
    assert!(!outcome.ok);
    let error = outcome.error.as_deref().unwrap_or("");
    assert!(error.contains("blob 0"), "{error}");
}

#[test]
fn missing_files_entry_fails() {
    let tmp = tmp_dir("bundle-missing-file");
    bundle_copy(&tmp);
    let manifest_path = tmp.join("manifest.json");
    let mut root = deg::json::parse(&fs::read_to_string(&manifest_path).unwrap()).unwrap();
    let Json::Obj(obj) = &mut root else {
        panic!("manifest is an object");
    };
    let Json::Arr(files) = obj.get_mut("files").unwrap() else {
        panic!("files is an array");
    };
    let mut entry = BTreeMap::new();
    entry.insert("path".to_string(), Json::Str("missing.bin".to_string()));
    entry.insert("sha256".to_string(), Json::Str("2".repeat(64)));
    files.push(Json::Obj(entry));
    reseal_manifest(obj);
    fs::write(&manifest_path, root.to_string()).unwrap();

    // Only the manifest dataset: the index pin is not under test here.
    let mut src = dataset_decl("ds_manifest", &tmp.join("manifest.json"));
    src.push_str("ev e := ntk_bundle(ds_manifest, \"bnd_deg_synthetic_752\");\n");
    let (_index, _artifacts, report) = run_evidence(&src, "e");
    let outcome = evidence_of(&report, "e");
    assert!(!outcome.ok);
    let error = outcome.error.as_deref().unwrap_or("");
    assert!(
        error.contains("files entry 1") && error.contains("missing"),
        "{error}"
    );
}

#[test]
fn index_without_packages_or_bundles_fails() {
    let tmp = tmp_dir("bundle-bad-index");
    bundle_copy(&tmp);
    fs::write(
        tmp.join("index.json"),
        "{\"schema\": \"kaze.capture-seal-index/v1\"}\n",
    )
    .unwrap();
    let src = bundle_model(&tmp);
    let (_index, _artifacts, report) = run_evidence(&src, "e");
    let outcome = evidence_of(&report, "e");
    assert!(!outcome.ok);
    let error = outcome.error.as_deref().unwrap_or("");
    assert!(
        error.contains("index has no packages/bundles array"),
        "{error}"
    );
}

#[test]
fn docs_style_verify_manifest_is_accepted() {
    // The documented schema generation: `verify` key, blobs with explicit
    // `path` entries, and a `packages` index array. Built by hand here so the
    // verifier's acceptance of the documented form is pinned independently of
    // the generated live-style fixture.
    let tmp = tmp_dir("bundle-verify-style");

    let blob_bytes = b"synthetic docs-style blob\n".to_vec();
    let blob_sha = sha256_hex(&blob_bytes);
    let blob_rel = format!(
        "blobs/sha256/{}/{}/{blob_sha}",
        &blob_sha[..2],
        &blob_sha[2..4]
    );
    let blob_file = tmp.join(&blob_rel);
    fs::create_dir_all(blob_file.parent().unwrap()).unwrap();
    fs::write(&blob_file, &blob_bytes).unwrap();

    let evidence_bytes = b"{\"schema\": \"kaze.capture-evidence/v1\", \"packets\": []}\n".to_vec();
    let evidence_sha = sha256_hex(&evidence_bytes);
    fs::write(tmp.join("evidence.json"), &evidence_bytes).unwrap();

    let payload = format!(
        r#"{{"schema":"kaze.bundle/v1","bundle_id":"bnd_docs_style",
        "evidence":{{"path":"evidence.json","sha256":"{evidence_sha}"}},
        "blobs":["{blob_rel}"]}}"#
    );
    let parsed = deg::json::parse(&payload).unwrap();
    let mut obj = parsed.as_obj().unwrap().clone();
    let digest =
        sha256_hex(deg_nexustk::bundle::canonical_json(&Json::Obj(obj.clone())).as_bytes());
    obj.insert(
        "verify".to_string(),
        Json::Obj({
            let mut sig = std::collections::BTreeMap::new();
            sig.insert("algorithm".to_string(), Json::Str("sha256".to_string()));
            sig.insert("sha256".to_string(), Json::Str(digest.clone()));
            sig
        }),
    );
    let manifest_text = Json::Obj(obj).to_string();
    fs::write(tmp.join("manifest.json"), &manifest_text).unwrap();
    let manifest_file_sha = sha256_hex(manifest_text.as_bytes());

    let index_text = format!(
        r#"{{"schema":"kaze.capture-seal-index/v1","packages":[
        {{"bundle_id":"bnd_docs_style","manifest":"manifest.json",
          "manifest_sha256":"{manifest_file_sha}","seal_sha256":"{digest}"}}]}}"#
    );
    fs::write(tmp.join("index.json"), &index_text).unwrap();

    let mut src = dataset_decl("ds_manifest", &tmp.join("manifest.json"));
    src.push_str(&dataset_decl("ds_index", &tmp.join("index.json")));
    src.push_str("ev e := ntk_bundle(ds_manifest, \"bnd_docs_style\", index_ds: ds_index);\n");
    let (_index, _artifacts, report) = run_evidence(&src, "e");
    let outcome = evidence_of(&report, "e");
    assert!(outcome.ok, "error: {:?}", outcome.error);
    assert_eq!(outcome.strength, Strength::Deterministic);
    assert!(has_fact(
        outcome,
        "bundle_verified",
        &[
            Value::sym("e"),
            Value::sym("bnd_docs_style"),
            Value::sym(manifest_file_sha),
        ]
    ));
}
